function dialLookup(dial, target) {
  for (let i = 0; i < dial.length; i++) if (dial[i] === target) return i;
  return -1;
}

function dialLookup(dial, target) {
  let lo = 0, hi = dial.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (dial[mid] === target) return mid;
    if (dial[lo] <= dial[mid]) {
      if (dial[lo] <= target && target < dial[mid]) hi = mid - 1;
      else lo = mid + 1;
    } else if (dial[mid] < target && target <= dial[hi]) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}
